      SUBROUTINE FNMTX(KNAME,LNAME,INAME)C---- FIND AND DECODE FIRST-, SECOND-, OR THIRD-ORDER TRANSFERC---- MATRIX ELEMENTC-----------------------------------------------------------------      CHARACTER*15    KNAME      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'PARDAT.CIN'C----------------------------------------------------------------      CHARACTER*15    KNAMM      CHARACTER*1     KLETS(8)      EQUIVALENCE     (KNAMM,KLETS(1))C      KNAMM = KNAME      INAME = 0C      IF (LNAME .GE. 6) GO TO 100      IF (KLETS(1) .EQ. 'R') THEN        IF (LNAME .GE. 4) GO TO 100        IND1 = INDEX('123456',KLETS(2))        IND2 = INDEX('123456',KLETS(3))        IF (IND1 .EQ. 0 .OR. IND1 .GT. 6) GO TO 100        IF (IND2 .EQ. 0 .OR. IND2 .GT. 6) GO TO 100        INAME = 1        J1 = IND1        IPARM = IND2      ELSE IF (KLETS(1) .EQ. 'T') THEN        IF (LNAME .GE. 5) GO TO 100        IND1 = INDEX('123456',KLETS(2))        IND2 = INDEX('123456',KLETS(3))        IND3 = INDEX('123456',KLETS(4))        IF (IND1 .EQ. 0 .OR. IND1 .GT. 6) GO TO 100        IF (IND2 .EQ. 0 .OR. IND2 .GT. 6) GO TO 100        IF (IND3 .EQ. 0 .OR. IND3 .GT. 6) GO TO 100        J1 = IND1        IPARM = 8        DO 20 I2 = 1, 6        DO 20 I3 = I2, 6        IPARM = IPARM + 1        IF (I2 .EQ. IND2 .AND. I3 .EQ. IND3) THEN          INAME = 1          GO TO 100        ENDIF   20   CONTINUE      ELSE IF (KLETS(1) .EQ. 'U') THEN        IND1 = INDEX('123456',KLETS(2))        IND2 = INDEX('123456',KLETS(3))        IND3 = INDEX('123456',KLETS(4))        IND4 = INDEX('123456',KLETS(5))        IF (IND1 .EQ. 0 .OR. IND1 .GT. 6) GO TO 100        IF (IND2 .EQ. 0 .OR. IND2 .GT. 6) GO TO 100        IF (IND3 .EQ. 0 .OR. IND3 .GT. 6) GO TO 100        IF (IND4 .EQ. 0 .OR. IND4 .GT. 6) GO TO 100        J1 = IND1        IPARM = 30        DO 30 I2 = 1, 6        DO 30 I3 = I2, 6        DO 30 I4 = I3, 6        IPARM = IPARM + 1        IF (I2 .EQ. IND2 .AND. I3 .EQ. IND3 .AND. I4 .EQ. IND4) THEN          INAME = 1          GO TO 100        ENDIF   30 CONTINUE      ENDIFC  100 CONTINUE      RETURN      END